package dev.jason.gboardpatches.extension.sharedmodel;
import org.junit.Test;
import static org.junit.Assert.*;
@org.junit.runner.RunWith(org.robolectric.RobolectricTestRunner.class)
@org.robolectric.annotation.Config(sdk=34,manifest=org.robolectric.annotation.Config.NONE)
public class SharedScreenCaptureTest {
 @Test public void boundedScreensAreAcceptedWithoutDimensionOverflow(){assertTrue(SharedScreenCaptureActivity.sizeAllowed(1272,2772));assertFalse(SharedScreenCaptureActivity.sizeAllowed(0,100));assertFalse(SharedScreenCaptureActivity.sizeAllowed(100000,100000));}
 @Test public void ordinaryPhonePhotosAreDownsampledBeforeBitmapAllocation(){int sample=SharedImageInputActivity.sampleSize(4032,3024);assertTrue(sample>=2);assertTrue(((4032-1)/sample+1)*(long)((3024-1)/sample+1)<=8000000L);assertEquals(1,SharedImageInputActivity.sampleSize(1272,2772));}
 @Test public void maliciousImageDimensionsCannotOverflowTheSamplingBound(){int sample=SharedImageInputActivity.sampleSize(Integer.MAX_VALUE,Integer.MAX_VALUE);assertTrue(sample>1);long edge=(Integer.MAX_VALUE-1L)/sample+1;assertTrue(edge<=4096);assertTrue(edge*edge<=8000000L);}
 @Test public void visibleMessagesAreContextAndOnlyExplicitPreferencesDefineUserStyle(){String text=SharedScreenContext.conversation("Alex: Can we meet Friday?","Use short sentences.");assertTrue(text.contains("Do not assume every message was written by the user."));assertTrue(text.contains("Alex: Can we meet Friday?"));assertTrue(text.contains("Explicit user-authored writing preferences"));assertTrue(text.endsWith("Use short sentences."));}
 @Test public void cleanupContinuesAfterOneNativeReleaseFails(){java.util.List<Integer> closed=new java.util.ArrayList<>();assertFalse(SharedScreenCaptureActivity.closeAll(()->{closed.add(1);throw new IllegalStateException();},()->closed.add(2),()->closed.add(3)));assertEquals(java.util.Arrays.asList(1,2,3),closed);}
 @Test public void failedCaptureLaunchDoesNotOccupyTheNextRequest(){android.content.Context failing=new android.content.ContextWrapper(org.robolectric.RuntimeEnvironment.getApplication()){@Override public void startActivity(android.content.Intent intent){throw new android.content.ActivityNotFoundException();}};int[] completed={0};SharedScreenCaptureActivity.capture(failing,image->{assertNull(image);completed[0]++;});SharedScreenCaptureActivity.capture(failing,image->{assertNull(image);completed[0]++;});assertEquals(2,completed[0]);}
 @Test public void failedPickerLaunchDoesNotOccupyTheNextRequest(){android.content.Context failing=new android.content.ContextWrapper(org.robolectric.RuntimeEnvironment.getApplication()){@Override public void startActivity(android.content.Intent intent){throw new android.content.ActivityNotFoundException();}};int[] completed={0};SharedImageInputActivity.choose(failing,image->{assertNull(image);completed[0]++;});SharedImageInputActivity.choose(failing,image->{assertNull(image);completed[0]++;});assertEquals(2,completed[0]);}
 @Test public void delayedCaptureDeliveryKeepsItsRequestAndRejectsAnOldResult()throws Exception{
  final android.content.Intent[] launched={null};android.content.Context context=new android.content.ContextWrapper(org.robolectric.RuntimeEnvironment.getApplication()){@Override public void startActivity(android.content.Intent intent){launched[0]=intent;}};
  java.util.List<android.graphics.Bitmap> first=new java.util.ArrayList<>(),blocked=new java.util.ArrayList<>(),next=new java.util.ArrayList<>();
  SharedScreenCaptureActivity.capture(context,first::add);String original=launched[0].getStringExtra("captureNonce");
  java.lang.reflect.Method finish=SharedScreenCaptureActivity.class.getDeclaredMethod("finishCapture",String.class,android.graphics.Bitmap.class);finish.setAccessible(true);
  android.graphics.Bitmap image=android.graphics.Bitmap.createBitmap(2,2,android.graphics.Bitmap.Config.ARGB_8888);finish.invoke(null,original,image);SharedScreenCaptureActivity.capture(context,blocked::add);assertEquals(0,first.size());assertEquals(1,blocked.size());assertNull(blocked.get(0));
  org.robolectric.Shadows.shadowOf(android.os.Looper.getMainLooper()).idleFor(java.time.Duration.ofMillis(450));assertSame(image,first.get(0));
  SharedScreenCaptureActivity.capture(context,next::add);String current=launched[0].getStringExtra("captureNonce");android.graphics.Bitmap stale=android.graphics.Bitmap.createBitmap(2,2,android.graphics.Bitmap.Config.ARGB_8888);finish.invoke(null,original,stale);assertTrue(stale.isRecycled());assertTrue(next.isEmpty());finish.invoke(null,current,null);org.robolectric.Shadows.shadowOf(android.os.Looper.getMainLooper()).idleFor(java.time.Duration.ofMillis(450));assertEquals(1,next.size());image.recycle();
 }
 @Test public void delayedPickerDeliveryKeepsItsTicketAndRejectsAnOldActivity()throws Exception{
  final android.content.Intent[] launched={null};android.content.Context context=new android.content.ContextWrapper(org.robolectric.RuntimeEnvironment.getApplication()){@Override public void startActivity(android.content.Intent intent){launched[0]=intent;}};
  java.util.List<android.graphics.Bitmap> first=new java.util.ArrayList<>(),blocked=new java.util.ArrayList<>(),next=new java.util.ArrayList<>();SharedImageInputActivity.choose(context,first::add);
  org.robolectric.android.controller.ActivityController<SharedImageInputActivity> original=org.robolectric.Robolectric.buildActivity(SharedImageInputActivity.class,launched[0]).setup();java.lang.reflect.Method complete=SharedImageInputActivity.class.getDeclaredMethod("complete",android.graphics.Bitmap.class);complete.setAccessible(true);
  android.graphics.Bitmap image=android.graphics.Bitmap.createBitmap(2,2,android.graphics.Bitmap.Config.ARGB_8888);complete.invoke(original.get(),image);SharedImageInputActivity.choose(context,blocked::add);assertEquals(0,first.size());assertEquals(1,blocked.size());assertNull(blocked.get(0));org.robolectric.Shadows.shadowOf(android.os.Looper.getMainLooper()).idleFor(java.time.Duration.ofMillis(600));assertSame(image,first.get(0));
  SharedImageInputActivity.choose(context,next::add);org.robolectric.android.controller.ActivityController<SharedImageInputActivity> current=org.robolectric.Robolectric.buildActivity(SharedImageInputActivity.class,launched[0]).setup();android.graphics.Bitmap stale=android.graphics.Bitmap.createBitmap(2,2,android.graphics.Bitmap.Config.ARGB_8888);complete.invoke(original.get(),stale);assertTrue(stale.isRecycled());assertTrue(next.isEmpty());complete.invoke(current.get(),new Object[]{null});org.robolectric.Shadows.shadowOf(android.os.Looper.getMainLooper()).idleFor(java.time.Duration.ofMillis(600));assertEquals(1,next.size());image.recycle();original.destroy();current.destroy();
 }
}
